class Element {
  constructor(props = {}) {
    this.id = props.id ?? 0;
    this.isDisplay = props.isDisplay ?? true;
    this.originX = props.originX ?? 0;
    this.originY = props.originY ?? 0;
    this.x = props.x ?? 0;
    this.y = props.y ?? 0;
    this.size = props.size ?? 100;
    this.w = this.size;
    this.h = this.size;
    this.scaleX = props.scaleX ?? 1;
    this.scaleY = props.scaleY ?? 1;
    this.angle = props.angle ?? 0;
    this.controlPointColor = color(255, 0, 0, 50);

    this.x1 = -width/2;
    this.y1 = random(0, 50) - height/2 + 30;
    this.x4 = width/2;
    this.y4 = random(0, -400) + height/2;
    this.ctrlDistance1 = random(300, 500);
    this.ctrlDistance2 = random(500, 1000);

    noFill();
  }

  run = (time, i) => {
    if (!this.isDisplay) return;
    push();

    translate(this.originX, this.originY);
    scale(this.scaleX, this.scaleY);
    rotate(this.angle);

    const waveOffset1 = sin(time + i * 0.00001) * 200;
    const waveOffset2 = sin(time + i * 0.005) * 50;
    const waveOffset3 = sin(time + i * 0.0001) * 30;
    const ctrlYOffset = sin(time + i * 0.01) * 8;

    const x1 = this.x1;
    const y1 = this.y1 + waveOffset3;
    const x2 = this.x1 + this.ctrlDistance1 + ctrlYOffset + waveOffset1;
    const y2 = this.y1;
    const x3 = this.x4 - this.ctrlDistance2 -  waveOffset2;
    const y3 = this.y4 + ctrlYOffset;
    const x4 = this.x4;
    const y4 = this.y4 + waveOffset2;

    const phase = this.id * 0.1;
    const alpha = map(sin(time * 2 + phase), -1, 1, 50, 255);
    strokeWeight(alpha * 0.006);
    stroke(color(0, 50));
    bezier(x1, y1, x2, y2, x3, y3, x4, y4);
    //this.drawBezierGuide(x1, y1, x2, y2, x3, y3, x4, y4);
    pop();
  }

  drawBezierGuide = (x1, y1, x2, y2, x3, y3, x4, y4) => {
    stroke(100, 30);
    line(x1, y1, x2, y2);
    line(x4, y4, x3, y3);
    noStroke();
    fill(255, 0, 0, 50);
    circle(x1, y1, 5);
    circle(x4, y4, 5);
    fill(0, 0, 255, 50);
    circle(x2, y2, 5);
    circle(x3, y3, 5);
  }
}

class Motif {
  constructor(props) {
    this.id = props.id ?? 0;
    this.isDisplay = props.isDisplay ?? true;
    this.originX = props.originX ?? 0;
    this.originY = props.originY ?? 0;
    this.x = props.x ?? 0;
    this.y = props.y ?? 0;
    this.size = props.size ?? 100;
    this.w = props.w ?? 100;
    this.h = props.h ?? 100;
    this.scaleX = props.scaleX ?? 1.0;
    this.scaleY = props.scaleY ?? 1.0;
    this.angle = props.angle ?? 0;
    this.repeat = props.repeat || 3000;

    this.elements = [];
    for (var i = 0; i < this.repeat; i++) {
      const element = new Element({
        id: i,
        originX: 0,
        originY: 0,
      })
      this.elements.push(element);
    }
  }

  run = () => {
    push();
    translate(this.originX, this.originY);
    rotate(this.angle);
    let time = millis() * 0.001;
    for (let i = 0; i < this.elements.length; i++) {
      const element = this.elements[i];
      element.run(time, i);
    }
    pop();
  }
}


